  except ValueError as error:assert 'profile' in str(error)
  else:raise AssertionError('wrong site accepted')
 elif ident=='fallback2':
  site={'spawn_s_m':{'passed_vehicle':90.0},'route_s_m':{'passed_vehicle':[90.0,110.0]}}
