 site['spawn_s_m']['passed_vehicle']=float(site['spawn_s_m']['passed_vehicle'])+offset
 site['route_s_m']=dict(site['route_s_m'])
 site['route_s_m']['passed_vehicle']=[float(s)+offset for s in site['route_s_m']['passed_vehicle']]
